class Solution:
    def splitArray(self, nums: list[int], k: int) -> int:
        lo,hi=max(nums),sum(nums)
        while lo<hi:
            mid=(lo+hi)//2;parts=1;total=0
            for x in nums:
                if total+x>mid:parts+=1;total=x
                else:total+=x
            if parts>k:lo=mid+1
            else:hi=mid
        return lo

class Solution {
    public int splitArray(int[] nums,int k) {
        long lo=0,hi=0;for(int x:nums){lo=Math.max(lo,x);hi+=x;}
        while(lo<hi){long mid=(lo+hi)/2;int parts=1;long sum=0;
            for(int x:nums){if(sum+x>mid){parts++;sum=x;}else sum+=x;}
            if(parts>k)lo=mid+1;else hi=mid;
        }return (int)lo;
    }
}

