class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        counts=[0]*26;left=0;max_freq=0;best=0
        for right,c in enumerate(s):
            x=ord(c)-65;counts[x]+=1;max_freq=max(max_freq,counts[x])
            while right-left+1-max_freq>k:
                counts[ord(s[left])-65]-=1;left+=1
            best=max(best,right-left+1)
        return best

class Solution {
    public int characterReplacement(String s,int k) {
        int[]cnt=new int[26];int left=0,maxFreq=0,best=0;
        for(int right=0;right<s.length();right++){int x=s.charAt(right)-'A';maxFreq=Math.max(maxFreq,++cnt[x]);
            while(right-left+1-maxFreq>k)cnt[s.charAt(left++)-'A']--;
            best=Math.max(best,right-left+1);
        }return best;
    }
}

