    public int minMutation(String startGene,String endGene,String[] bank) {
        if(startGene.equals(endGene))return 0;Set<String>allowed=new HashSet<>(Arrays.asList(bank));if(!allowed.contains(endGene))return -1;
        Queue<String>q=new ArrayDeque<>();Map<String,Integer>d=new HashMap<>();q.offer(startGene);d.put(startGene,0);char[]bases={'A','C','G','T'};
        while(!q.isEmpty()){String g=q.poll();int dist=d.get(g);char[]a=g.toCharArray();
            for(int i=0;i<a.length;i++){char old=a[i];for(char b:bases){a[i]=b;String next=new String(a);if(next.equals(endGene))return dist+1;if(allowed.contains(next)&&!d.containsKey(next)){d.put(next,dist+1);q.offer(next);}}a[i]=old;}
        }return -1;
    }
}

