class Solution:
    def deleteNode(self, root, key: int):
        if not root:return None
        if key<root.val:root.left=self.deleteNode(root.left,key)
        elif key>root.val:root.right=self.deleteNode(root.right,key)
        else:
            if not root.left:return root.right
            if not root.right:return root.left
            succ=root.right
            while succ.left:succ=succ.left
            root.val=succ.val
            root.right=self.deleteNode(root.right,succ.val)
        return root

class Solution {
    public TreeNode deleteNode(TreeNode root,int key) {
        if(root==null)return null;
        if(key<root.val)root.left=deleteNode(root.left,key);
        else if(key>root.val)root.right=deleteNode(root.right,key);
        else{if(root.left==null)return root.right;if(root.right==null)return root.left;TreeNode s=root.right;while(s.left!=null)s=s.left;root.val=s.val;root.right=deleteNode(root.right,s.val);}
        return root;
    }
}

