        Map<Character,Integer>c=new HashMap<>();for(char x:s.toCharArray())c.put(x,c.getOrDefault(x,0)+1);
        List<Character>keys=new ArrayList<>(c.keySet());keys.sort((a,b)->Integer.compare(c.get(b),c.get(a)));
