class Solution:
    def findMinArrowShots(self, points: list[list[int]]) -> int:
        if not points:return 0
        points.sort(key=lambda p:p[1]);arrows=1;end=points[0][1]
        for start,finish in points[1:]:
            if start>end:arrows+=1;end=finish
        return arrows

import java.util.*;
class Solution {
    public int findMinArrowShots(int[][] points) {
        if(points.length==0)return 0;Arrays.sort(points,Comparator.comparingLong(a->(long)a[1]));int arrows=1;long end=points[0][1];
        for(int i=1;i<points.length;i++)if((long)points[i][0]>end){arrows++;end=points[i][1];}
        return arrows;
    }
}

