class Solution:
    def makesquare(self, matchsticks: list[int]) -> bool:
        total=sum(matchsticks)
        if total%4:return False
        target=total//4;matchsticks.sort(reverse=True)
        if matchsticks and matchsticks[0]>target:return False
        sides=[0]*4
        def dfs(i):
            if i==len(matchsticks):return all(x==target for x in sides)
            x=matchsticks[i];seen=set()
            for j in range(4):
                if sides[j] in seen or sides[j]+x>target:continue
                seen.add(sides[j]);sides[j]+=x
                if dfs(i+1):return True
                sides[j]-=x
                if sides[j]==0:break
            return False
        return dfs(0)

import java.util.*;
class Solution {
    private int[] sticks;private int target;private int[] sides;
    public boolean makesquare(int[] matchsticks) {
        int total=0;for(int x:matchsticks)total+=x;if(total%4!=0)return false;target=total/4;sticks=matchsticks.clone();Arrays.sort(sticks);for(int i=0,j=sticks.length-1;i<j;i++,j--){int t=sticks[i];sticks[i]=sticks[j];sticks[j]=t;}
        if(sticks.length>0&&sticks[0]>target)return false;sides=new int[4];return dfs(0);
    }
    private boolean dfs(int i){if(i==sticks.length)return sides[0]==target&&sides[1]==target&&sides[2]==target;
        Set<Integer>seen=new HashSet<>();for(int j=0;j<4;j++){if(!seen.add(sides[j])||sides[j]+sticks[i]>target)continue;sides[j]+=sticks[i];if(dfs(i+1))return true;sides[j]-=sticks[i];if(sides[j]==0)break;}return false;}
}

class Solution:
    def findMaxForm(self, strs: list[str], m: int, n: int) -> int:
        dp=[[0]*(n+1) for _ in range(m+1)]
        for s in strs:
            zeros=s.count('0');ones=len(s)-zeros
            for i in range(m,zeros-1,-1):
                for j in range(n,ones-1,-1):dp[i][j]=max(dp[i][j],1+dp[i-zeros][j-ones])
        return dp[m][n]

class Solution {
    public int findMaxForm(String[] strs,int m,int n) {
        int[][]dp=new int[m+1][n+1];
        for(String s:strs){int z=0;for(char c:s.toCharArray())if(c=='0')z++;int o=s.length()-z;
            for(int i=m;i>=z;i--)for(int j=n;j>=o;j--)dp[i][j]=Math.max(dp[i][j],1+dp[i-z][j-o]);
        }return dp[m][n];
    }
}

from bisect import bisect_left
class Solution:
    def findRadius(self, houses: list[int], heaters: list[int]) -> int:
        heaters.sort();answer=0
        for h in houses:
            i=bisect_left(heaters,h);left=h-heaters[i-1] if i>0 else float('inf');right=heaters[i]-h if i<len(heaters) else float('inf')
            answer=max(answer,min(left,right))
        return answer

import java.util.*;
class Solution {
    public int findRadius(int[] houses,int[] heaters) {
        Arrays.sort(heaters);int ans=0;
        for(int h:houses){int i=Arrays.binarySearch(heaters,h);if(i<0)i=-i-1;long left=i>0?(long)h-heaters[i-1]:Long.MAX_VALUE;long right=i<heaters.length?(long)heaters[i]-h:Long.MAX_VALUE;ans=(int)Math.max(ans,Math.min(left,right));}
        return ans;
    }
}

